// Compile-time assertion that parserImpl satisfies sdk.MetadataSource (the one
// capability interface this plugin ships). The sdk.MetadataSourcePlugin adapter
// forwards the four unary RPCs here. Mirrors plugins/tv-parser/parser.go.
var _ sdk.MetadataSource = (*parserImpl)(nil)

// parserImpl is the server-side MetadataSource capability for serial-parser.
// It is STATELESS between RPCs: every output is a pure function of the request.
// The plugin self-selects PER DOCUMENT at Match (serials-library D5): a SERIES
// document (parsed carries the serial-record marker) parses the raw directory
// facts into a cleaned display title + season; an EPISODE document applies iff
// its filename yields an episode number (SxxExx or a bare-number form) and
// parses the episode numbers. Anything
// else is applies=false — a skipped stage, not an error. Merge writes ONLY
// sources["serial-parser"]; the core stamps _provenance/_view authoritatively
// (INV-namespace-write). A local parser: BuildRequest is a nop (no fetch), and
// the interactive search pair is declined via the embedded sdk.UnsupportedSearch
// base (identify-match-override).
type parserImpl struct {
	sdk.UnsupportedSearch
}

// Marker fact names the serial-scanner stamps into parsed (design.md
// §Interfaces §1-2). Read here as plain facts — the plugin never imports core.
const (
	factSerialRecord       = "serial_record"
	factDirNameRaw         = "dir_name_raw"
	factSeriesRelativePath = "series_relative_path"
	factRelativePath       = "relative_path"
)

// Match self-selects per document. A serial-record document parses the raw
// directory name (dir_name_raw, falling back to the series path); an episode
// document applies iff its filename carries an SxxExx token; a numberless
// VIDEO filename follows the film path (title + release fields, never a
// season or episode key). Non-applying documents are skipped stages recorded
// by the core (not errors).
func (*parserImpl) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	f := req.GetItem().GetParsed().GetFields()
	if f[factSerialRecord].GetBoolValue() {
		raw := f[factDirNameRaw].GetStringValue()
		if raw == "" {
			raw = f[factSeriesRelativePath].GetStringValue()
		}
		if raw == "" {
			return &metadatav1.MatchResult{Applies: false, Reason: "serial record without directory facts"}, nil
		}
		res, season, explicit := parseSeriesDir(raw)
		confidence := 0.6
		if explicit {
			confidence = 1.0
		}
		q := map[string]any{
			"title":        res.Title,
			"dir_name_raw": raw,
			"season":       int64(season), // always present: marker value, else 1
		}
		emitReleaseFields(q, res)
		query, _ := structpb.NewStruct(q)
		return &metadatav1.MatchResult{
			Applies:    true,
			Query:      query, // the parsed directory facts become the chain's query
			Confidence: confidence,
			Reason:     "serial-record directory facts",
		}, nil
	}

	rel := parsedString(f, factRelativePath)
	res, season, ok := parseEpisodeFilename(rel, parsedString(f, factSeriesRelativePath))
	if !ok {
		return matchFilmFilename(rel), nil
	}
	q := map[string]any{
		"season":  int64(season),
		"episode": int64(res.Episode),
	}
	if res.EpisodeEnd > 0 {
		q["episode_end"] = int64(res.EpisodeEnd)
	}
	emitReleaseFields(q, res)
	query, _ := structpb.NewStruct(q)
	return &metadatav1.MatchResult{
		Applies:    true,
		Query:      query,
		Confidence: 1.0,
		Reason:     "episode filename number",
	}, nil
}

// matchFilmFilename is the film-path fallthrough (film-name-parsing 2.1): a
// numberless VIDEO filename parses through the shared grammar's no-season
// parse and applies at confidence 0.6 with title plus the structured release
// fields — NEVER a season or episode key, even when the name carries a season
// marker (Show.S01.mkv: the marker is dropped on the film path; the
// always-season rule is series-scoped). A non-video name or an empty-title
// parse stays a skipped stage with a reason.
func matchFilmFilename(rel string) *metadatav1.MatchResult {
	base := filepath.Base(rel)
	if !releasename.HasVideoExt(base) {
		return &metadatav1.MatchResult{Applies: false, Reason: "no episode number in a non-video filename"}
	}
	res := releasename.ParseName(base)
	if res.Title == "" {
		return &metadatav1.MatchResult{Applies: false, Reason: "film filename parsed to an empty title"}
	}
	q := map[string]any{"title": res.Title}
	emitReleaseFields(q, res)
	query, _ := structpb.NewStruct(q)
	return &metadatav1.MatchResult{
		Applies:    true,
		Query:      query,
		Confidence: 0.6,
		Reason:     "film filename parse",
	}
}

// BuildRequest returns an empty RequestSpec: a local parser performs no
// external fetch (the fetch between BuildRequest and Convert is a no-op stub).
// The query is carried forward to Convert by the core. Mirrors tv-parser.
func (*parserImpl) BuildRequest(_ context.Context, _ *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{Spec: &metadatav1.RequestSpec{}}, nil
}

// Convert normalizes the Match query into the contributed metadata. For a local
// parser the metadata IS the parsed query fields (identity normalization).
func (*parserImpl) Convert(_ context.Context, req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	meta := structFromQuery(req.GetQuery())
	return &metadatav1.ConvertResult{
		Metadata:   meta,
		Provenance: provenanceHints(meta),
	}, nil
}

// Merge writes ONLY the sources.<plugin_id> namespace (the plugin_id is the
// core-supplied namespace id). The plugin never touches
// _provenance/_view/_stages; the returned View bindings are a proposal the core
// recomputes authoritatively. Verbatim mirror of tv-parser's Merge.
func (*parserImpl) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	id := req.GetPluginId()
	if id == "" {
		id = pluginID
	}
	meta := map[string]any{}
	if req.GetIncoming() != nil {
		meta = req.GetIncoming().AsMap()
	}
	data, _ := structpb.NewStruct(map[string]any{
		"sources": map[string]any{id: meta},
	})
	view := make([]*commonv1.ViewBinding, 0, len(meta))
	for field := range meta {
		view = append(view, &commonv1.ViewBinding{FieldPath: field, Source: id, Reason: "priority"})
	}
	return &metadatav1.MergeResult{
		Document: &commonv1.MediaDocument{Data: data},
		View:     view,
	}, nil
}

// parsedString reads a string fact from a parsed Struct field map, "" when
// absent or not a string.
func parsedString(fields map[string]*structpb.Value, key string) string {
	return fields[key].GetStringValue()
}

// structFromQuery rebuilds the metadata Struct from the Match query (identity
// normalization — there is no upstream response to fold in). Mirrors tv-parser.
func structFromQuery(query *structpb.Struct) *structpb.Struct {
	if query == nil {
		return &structpb.Struct{}
	}
	st, _ := structpb.NewStruct(query.AsMap())
	return st
}

// provenanceHints builds the per-field provenance hint map the core merges over
// its authoritative _provenance stamp. Mirrors tv-parser.
func provenanceHints(meta *structpb.Struct) map[string]*commonv1.Provenance {
	fields := meta.GetFields()
	out := make(map[string]*commonv1.Provenance, len(fields))
	fetched := timestamppb.Now()
	for field := range fields {
		out[field] = &commonv1.Provenance{
			PluginId:      pluginID,
			PluginVersion: pluginVersion,
			FetchedAt:     fetched,
		}
	}
	return out
}
